    content: `
# Gift Affidavit: How to Document a Gift of Money, a Car, or Property

**Disclaimer:** This article provides general educational information about gift affidavits and is not legal or tax advice. Requirements vary by state, lender, and the IRS. For advice about your situation, consult a licensed attorney or tax professional.

---

A **gift affidavit** is a sworn statement confirming that something of value — money, a vehicle, or property — was given as a **true gift**, with **no expectation of repayment**. That single fact matters a great deal: it determines whether a transfer is treated as a loan, affects mortgage approvals, and can have tax and title consequences.

## What a Gift Affidavit Proves

It establishes, under oath, that:

- The item or money was **freely given**
- The recipient owes **nothing in return** (it is not a loan)
- The **giver (donor)** had the right to give it

## Common Uses

- **Vehicle transfers** — gifting a car to a family member, often to avoid sales tax that would apply to a sale
- **Mortgage down payments** — lenders require a **gift letter or affidavit** proving down-payment money is a gift, not a loan that would affect the buyer's debt
- **Large cash gifts** — documenting a gift for the record or for tax purposes
- **Property transfers** — confirming a gift rather than a sale

## Why Lenders and the DMV Care

- **Lenders** must know that down-payment funds will not have to be repaid, because a hidden loan changes the borrower's debt-to-income ratio. A signed gift affidavit (often called a **gift letter**) satisfies this.
- **The DMV** treats a gifted vehicle differently from a sold one. A gift affidavit can establish that no money changed hands, which affects how tax is assessed on the transfer.

## What a Gift Affidavit Includes

1. The **donor's name and address** (the giver)
2. The **recipient's name and address** (the donee)
3. The **relationship** between them
4. A **description of the gift** (amount of money, or vehicle VIN / property details)
5. The **date** of the gift
6. A clear statement that it is a **gift with no repayment expected**
7. A statement that the donor gave it **voluntarily**
8. **Signatures**, usually sworn before a notary

## A Note on Gift Taxes

Large gifts can have **federal gift tax** implications for the giver. There is an **annual exclusion amount** (adjusted yearly) you can give per recipient without filing a gift tax return, and a much larger lifetime exemption above that. A gift affidavit documents the gift but does not by itself handle tax reporting — for sizable gifts, talk to a tax professional about whether a gift tax return is required.

## Common Mistakes

❌ Describing a loan as a gift to qualify for a mortgage (this is fraud)
❌ Leaving out the explicit "no repayment expected" statement
❌ Vague descriptions (omitting the VIN, amount, or property details)
❌ Forgetting notarization where the DMV or lender requires it
❌ Ignoring gift tax reporting for large gifts

## Frequently Asked Questions

**Q: What is a gift affidavit?**
A: A sworn statement confirming that money, a vehicle, or property was given as a true gift with no expectation of repayment.

**Q: Why do I need a gift affidavit for a car?**
A: It documents that the vehicle was gifted rather than sold, which affects how the DMV assesses transfer tax and proves no money changed hands.

**Q: What is a gift letter for a mortgage?**
A: It is a gift affidavit stating that down-payment funds are a gift, not a loan. Lenders require it so the money is not counted as new debt.

**Q: Do gift affidavits affect taxes?**
A: The affidavit documents the gift, but large gifts may trigger federal gift tax reporting for the giver. There is an annual exclusion amount; consult a tax professional for sizable gifts.

**Q: Does a gift affidavit need to be notarized?**
A: Usually yes, especially when required by the DMV or a lender. Sign it before a notary with valid ID.

## How discover.legal Helps

Our platform builds a clear, notary-ready gift affidavit for a vehicle, cash, or property gift, with the precise "no repayment expected" language lenders and the DMV look for. We do not provide legal or tax advice.

[Create a Gift Affidavit →](#cta)
`
