    title: 'How to Modify a Custody or Child Support Order',
    description: 'Learn how to change a custody or child support order after your case is final, what counts as a substantial change in circumstances, and the court process.',
    category: 'Guides',
    readTime: '7 min read',
    publishDate: 'March 31, 2026',
