// Helper function to get article by slug
export const getArticleBySlug = (slug) => {
  return ARTICLES.find(article => article.slug === slug);
};

// Helper function to get featured articles
export const getFeaturedArticles = () => {
  return ARTICLES.filter(article => article.featured);
};

// Helper function to get articles by category
export const getArticlesByCategory = (category) => {
  return ARTICLES.filter(article => article.category === category);
};

// Get all unique categories
export const getCategories = () => {
  return [...new Set(ARTICLES.map(article => article.category))];
};

/**
 * Whether an article should surface in the given locale.
 * Missing `locale` field is treated as 'us' (backward compatible default).
 */
const matchesLocale = (article, locale) => {
  const tag = article.locale ?? 'us';
  return tag === 'both' || tag === locale;
};

// Locale-aware variants used by the server-rendered /resources page.
export const getArticlesForLocale = (locale) => {
  return ARTICLES.filter((a) => matchesLocale(a, locale));
};

export const getFeaturedArticlesForLocale = (locale) => {
  return ARTICLES.filter((a) => a.featured && matchesLocale(a, locale));
};

export const getCategoriesForLocale = (locale) => {
  return [...new Set(
    ARTICLES.filter((a) => matchesLocale(a, locale)).map((a) => a.category),
  )];
};
